package hikyubank;
import java.util.*;import java.math.BigDecimal;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.jdbc.core.JdbcTemplate;
import hikyubank.application.service.*;import hikyubank.application.dto.PaymentDtos.*;import hikyubank.application.dto.SecurityDtos.Registration;import hikyubank.application.dto.ExtensionDtos.TransferInput;import hikyubank.application.service.PaymentAuthorizationService.*;import hikyubank.application.exception.BankException;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest class PaymentIntegrationTest {
 @Autowired SecurityService security;@Autowired AccountService accounts;@Autowired PaymentService payments;@Autowired PaymentAuthorizationService authorization;@Autowired TransferService transfers;@Autowired NotificationService notifications;@Autowired AlertService alerts;@Autowired TransactionQueryService queries;@Autowired JdbcTemplate jdbc;
 UUID sender,receiver,source,target,saving;String senderName,receiverName;final String session="test-session",pin="0371";
 @DynamicPropertySource static void db(DynamicPropertyRegistry p){BankApiIntegrationTest.databaseProperties(p);}
 @BeforeEach void users(){senderName="payer_"+UUID.randomUUID().toString().substring(0,8);receiverName="payee_"+UUID.randomUUID().toString().substring(0,8);sender=security.register(new Registration(senderName,"Sender","Test","TestingPassword2026!",pin)).userId();receiver=security.register(new Registration(receiverName,"Receiver","Test","TestingPassword2026!","9912")).userId();source=accounts.list(sender).stream().filter(a->a.type().equals("checking")).findFirst().orElseThrow().id();saving=accounts.list(sender).stream().filter(a->a.type().equals("savings")).findFirst().orElseThrow().id();target=accounts.list(receiver).stream().filter(a->a.type().equals("checking")).findFirst().orElseThrow().id();}
 Input input(String amount,UUID key){return new Input(source,receiverName,new BigDecimal(amount),"Demo payment",key,pin);}
 Challenge challenge(Input p,String method){return authorization.issue(sender,session,new ChallengeRequest("peer",p.sourceAccountId(),null,p.recipientUsername(),p.amount(),p.note(),p.idempotencyKey(),method));}
 Receipt send(Input p,Challenge c){return authorization.execute(sender,session,PaymentAuthorizationService.peer(p),c.challengeId(),c.demoCode(),()->payments.send(sender,p));}
 BigDecimal balance(UUID user,UUID id){return accounts.get(user,id).balance();}
 @Test void verifiedPeerPaymentPostsBalancedLegsAndBothHistories(){var p=input("75.25",UUID.randomUUID());var c=challenge(p,"sms");var r=send(p,c);assertEquals(new BigDecimal("924.75"),balance(sender,source));assertEquals(new BigDecimal("1075.25"),balance(receiver,target));assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM hikyu.transactions WHERE peer_payment_id=?",Integer.class,r.id()));assertEquals(0,jdbc.queryForObject("SELECT sum(amount) FROM hikyu.transactions WHERE peer_payment_id=?",BigDecimal.class,r.id()).signum());assertEquals("sent",payments.history(sender).get(0).direction());assertEquals("received",payments.history(receiver).get(0).direction());assertEquals(1,notifications.list(sender).size());assertEquals(1,notifications.list(receiver).size());assertEquals("Checking ending "+accounts.get(receiver,target).suffix(),payments.lookup(sender,new Lookup(receiverName)).accountLabel());}
 @Test void internalNeedsCodeAndDoesNotNeedPin(){var p=new TransferInput(source,saving,new BigDecimal("25"),"",UUID.randomUUID(),null);var c=authorization.issue(sender,session,new ChallengeRequest("internal",source,saving,null,p.amount(),p.note(),p.idempotencyKey(),"email"));assertThrows(BankException.class,()->authorization.execute(sender,session,PaymentAuthorizationService.internal(p),null,null,()->transfers.transferVerified(sender,p)));authorization.execute(sender,session,PaymentAuthorizationService.internal(p),c.challengeId(),c.demoCode(),()->transfers.transferVerified(sender,p));assertEquals(new BigDecimal("975.00"),balance(sender,source));}
 @Test void peerRequiresBothCodeAndCorrectPin(){var p=input("20",UUID.randomUUID());var c=challenge(p,"email");assertEquals("PAYMENT_VERIFICATION_REQUIRED",assertThrows(BankException.class,()->authorization.execute(sender,session,PaymentAuthorizationService.peer(p),null,null,()->payments.send(sender,p))).code());var bad=new Input(source,receiverName,p.amount(),p.note(),p.idempotencyKey(),"0000");assertThrows(BankException.class,()->send(bad,c));assertEquals(new BigDecimal("1000.00"),balance(sender,source));assertFalse(jdbc.queryForObject("SELECT consumed FROM hikyu.payment_verifications WHERE id=?",Boolean.class,c.challengeId()));send(p,c);}
 @Test void codeIsBoundToPayloadUserAndLoginSession(){var p=input("20",UUID.randomUUID());var c=challenge(p,"sms");var changed=input("21",p.idempotencyKey());assertEquals("PAYMENT_VERIFICATION_MISMATCH",assertThrows(BankException.class,()->send(changed,c)).code());assertThrows(BankException.class,()->authorization.execute(sender,"different-session",PaymentAuthorizationService.peer(p),c.challengeId(),c.demoCode(),()->payments.send(sender,p)));assertThrows(BankException.class,()->authorization.execute(receiver,session,PaymentAuthorizationService.peer(p),c.challengeId(),c.demoCode(),()->payments.send(sender,p)));assertEquals(new BigDecimal("1000.00"),balance(sender,source));}
 @Test void wrongCodeLockoutExpiryAndIssuanceRate(){var p=input("20",UUID.randomUUID());var c=challenge(p,"sms");String wrong=c.demoCode().equals("000000")?"111111":"000000";for(int i=0;i<5;i++)assertThrows(BankException.class,()->authorization.execute(sender,session,PaymentAuthorizationService.peer(p),c.challengeId(),wrong,()->payments.send(sender,p)));assertEquals(5,jdbc.queryForObject("SELECT attempts FROM hikyu.payment_verifications WHERE id=?",Integer.class,c.challengeId()));assertEquals("PAYMENT_VERIFICATION_LOCKED",assertThrows(BankException.class,()->send(p,c)).code());var exp=challenge(p,"email");jdbc.update("UPDATE hikyu.payment_verifications SET expires_at=TIMESTAMPTZ '2000-01-01' WHERE id=?",exp.challengeId());assertEquals("PAYMENT_VERIFICATION_EXPIRED",assertThrows(BankException.class,()->send(p,exp)).code());for(int i=0;i<8;i++)challenge(p,"sms");assertEquals(429,assertThrows(BankException.class,()->challenge(p,"sms")).status());}
 @Test void replayIsOnePaymentAndConflictingKeyCannotChangeIt(){var key=UUID.randomUUID();var p=input("15",key);var c=challenge(p,"sms");var r=send(p,c);assertEquals(r.id(),send(p,c).id());assertEquals(1,payments.history(sender).size());assertEquals(1,notifications.list(sender).size());var changed=input("16",key);var c2=challenge(changed,"email");assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BankException.class,()->send(changed,c2)).code());assertEquals(new BigDecimal("985.00"),balance(sender,source));}
 @Test void concurrentSameCodeAndKeyNeverDoubleDebit()throws Exception{var p=input("30",UUID.randomUUID());var c=challenge(p,"sms");var pool=Executors.newFixedThreadPool(6);try{var tasks=new ArrayList<Callable<UUID>>();for(int i=0;i<12;i++)tasks.add(()->send(p,c).id());var ids=new HashSet<UUID>();for(var f:pool.invokeAll(tasks))ids.add(f.get(15,TimeUnit.SECONDS));assertEquals(1,ids.size());assertEquals(new BigDecimal("970.00"),balance(sender,source));assertEquals(1,notifications.list(receiver).size());}finally{pool.shutdownNow();}}
 @Test void opposingPaymentsUseStableLockOrder()throws Exception{var a=input("100",UUID.randomUUID());var ac=challenge(a,"sms");var b=new Input(target,senderName,new BigDecimal("200"),"Return",UUID.randomUUID(),"9912");var bc=authorization.issue(receiver,"receiver-session",new ChallengeRequest("peer",target,null,senderName,b.amount(),b.note(),b.idempotencyKey(),"email"));var pool=Executors.newFixedThreadPool(2);try{var futures=pool.invokeAll(List.<Callable<UUID>>of(()->send(a,ac).id(),()->authorization.execute(receiver,"receiver-session",PaymentAuthorizationService.peer(b),bc.challengeId(),bc.demoCode(),()->payments.send(receiver,b)).id()));for(var future:futures)assertNotNull(future.get(15,TimeUnit.SECONDS));assertEquals(new BigDecimal("2000.00"),balance(sender,source).add(balance(receiver,target)));assertEquals(new BigDecimal("1100.00"),balance(sender,source));}finally{pool.shutdownNow();}}
 @Test void insufficientInvalidForeignSelfAndUnknownAreRejected(){var p=input("1001",UUID.randomUUID());var c=challenge(p,"sms");assertEquals("INSUFFICIENT_FUNDS",assertThrows(BankException.class,()->send(p,c)).code());assertTrue(notifications.list(sender).isEmpty());for(String a:List.of("0","-1","1.001"))assertThrows(BankException.class,()->payments.send(sender,input(a,UUID.randomUUID())));var foreign=new Input(target,receiverName,BigDecimal.ONE,"",UUID.randomUUID(),pin);assertEquals(404,assertThrows(BankException.class,()->payments.send(sender,foreign)).status());assertThrows(BankException.class,()->payments.lookup(sender,new Lookup(senderName)));assertThrows(BankException.class,()->payments.lookup(sender,new Lookup("unknown_user")));assertEquals(new BigDecimal("1000.00"),balance(sender,source));}
 @Test void secondLegFailureRollsBackPaymentBalancesNotificationsAndCode(){var p=input("10",UUID.randomUUID());var c=challenge(p,"sms");jdbc.execute("CREATE FUNCTION hikyu.test_reject_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.name LIKE 'Payment from %' THEN RAISE EXCEPTION 'test failure'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER test_reject_payment BEFORE INSERT ON hikyu.transactions FOR EACH ROW EXECUTE FUNCTION hikyu.test_reject_payment()");try{assertThrows(Exception.class,()->send(p,c));assertEquals(new BigDecimal("1000.00"),balance(sender,source));assertEquals(new BigDecimal("1000.00"),balance(receiver,target));assertTrue(payments.history(sender).isEmpty());assertTrue(notifications.list(sender).isEmpty());assertFalse(jdbc.queryForObject("SELECT consumed FROM hikyu.payment_verifications WHERE id=?",Boolean.class,c.challengeId()));}finally{jdbc.execute("DROP TRIGGER test_reject_payment ON hikyu.transactions");jdbc.execute("DROP FUNCTION hikyu.test_reject_payment()");}send(p,c);}
 @Test void notificationsAreDeduplicatedAndDisabledRulesDoNotFire(){var rule=alerts.create(sender,new hikyubank.application.dto.BankDtos.AlertRequest("large_transaction",source,"Large payment","In-app",new BigDecimal("10"),null));var p=input("20",UUID.randomUUID());var c=challenge(p,"sms");send(p,c);send(p,c);assertEquals(2,notifications.list(sender).size());alerts.toggle(sender,rule.id(),false);var p2=input("20",UUID.randomUUID());send(p2,challenge(p2,"email"));assertEquals(3,notifications.list(sender).size());}
 @Test void paymentQueryKeepsUserIsolationAndIncomeExpenseMeaning(){var p=input("42",UUID.randomUUID());send(p,challenge(p,"sms"));assertEquals(1,queries.search(sender,null,null,null,null,null,"peer_transfer","","","date_desc",0,10).total());assertEquals(1,queries.search(sender,null,null,null,null,null,"expense","","","date_desc",0,10).total());assertEquals(0,queries.search(sender,null,null,null,null,null,"income","","","date_desc",0,10).total());assertEquals(1,queries.search(receiver,null,null,null,null,null,"income","","","date_desc",0,10).total());assertEquals(0,queries.search(sender,null,null,null,null,null,"transfer","","","date_desc",0,10).total());var third=security.register(new Registration("third_"+senderName,"Third","User","TestingPassword2026!","1717")).userId();assertTrue(payments.history(third).isEmpty());assertThrows(BankException.class,()->queries.detail(third,queries.search(sender,null,null,null,null,null,"peer_transfer","","","date_desc",0,10).items().get(0).id()));}
 @Test void concurrentDistinctPeerPaymentsCannotOverdraw()throws Exception{var a=input("700",UUID.randomUUID());var b=input("700",UUID.randomUUID());var ac=challenge(a,"sms");var bc=challenge(b,"email");var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<Boolean>>of(()->{try{send(a,ac);return true;}catch(BankException e){assertEquals("INSUFFICIENT_FUNDS",e.code());return false;}},()->{try{send(b,bc);return true;}catch(BankException e){assertEquals("INSUFFICIENT_FUNDS",e.code());return false;}}));int successes=0;for(var result:results)if(result.get(15,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(new BigDecimal("300.00"),balance(sender,source));assertEquals(new BigDecimal("1700.00"),balance(receiver,target));assertEquals(1,payments.history(sender).size());assertEquals(1,notifications.list(receiver).size());}finally{pool.shutdownNow();}}

}
